const questions = [
  {
    id: 'q1',
    text: 'Which of these languages are considered low-level or provide low-level memory management?',
    helpText: 'Low-level languages provide little or no abstraction from a computer\'s instruction set architecture.',
    options: [
      { id: 'q1-c', label: 'C' },
      { id: 'q1-rust', label: 'Rust' },
      { id: 'q1-python', label: 'Python' },
      { id: 'q1-asm', label: 'Assembly' }
    ]
  },
  {
    id: 'q2',
    text: 'Which of the following are commonly used for front-end web development?',
    options: [
      { id: 'q2-js', label: 'JavaScript' },
      { id: 'q2-ts', label: 'TypeScript' },
      { id: 'q2-swift', label: 'Swift' },
      { id: 'q2-css', label: 'HTML/CSS' }
    ]
  },
  {
    id: 'q3',
    text: 'Which languages were created at least partially to run on the Java Virtual Machine (JVM)?',
    options: [
      { id: 'q3-java', label: 'Java' },
      { id: 'q3-kotlin', label: 'Kotlin' },
      { id: 'q3-scala', label: 'Scala' },
      { id: 'q3-ruby', label: 'Ruby' }
    ]
  }
];

const Quiz = () => {
  const [selected, setSelected] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const handleToggle = (questionId, optionId) => {
    setSelected(prev => {
      const current = prev[questionId] || [];
      const next = current.includes(optionId)
        ? current.filter(id => id !== optionId)
        : [...current, optionId];
      return { ...prev, [questionId]: next };
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
    console.log('Quiz submitted:', selected);
  };

  if (submitted) {
    return (
      <div className="quiz-container">
        <h1>Thank you!</h1>
        <p className="description">Your responses have been recorded.</p>
        <div className="results">
            <p>You selected {Object.values(selected).flat().length} total answers.</p>
        </div>
        <button className="submit-btn" style={{marginTop: '1rem'}} onClick={() => setSubmitted(false)}>Retake Quiz</button>
      </div>
    );
  }

  return (
    <div className="quiz-container">
      <h1>Computer Languages Quiz</h1>
      <p className="description">Test your knowledge of programming languages. Select all that apply.</p>

      <form onSubmit={handleSubmit}>
        {questions.map((q, idx) => (
          <div key={q.id} className="form-field">
            <fieldset style={{border: 'none', padding: 0, margin: 0}}>
              <legend className="question-legend">{idx + 1}. {q.text}</legend>
              {q.helpText && (
                <span id={`${q.id}-help`} className="help-text">{q.helpText}</span>
              )}
              <div className="options-grid">
                {q.options.map(option => (
                  <label key={option.id} className="option-label">
                    <input
                      type="checkbox"
                      checked={(selected[q.id] || []).includes(option.id)}
                      onChange={() => handleToggle(q.id, option.id)}
                      aria-describedby={q.helpText ? `${q.id}-help` : undefined}
                    />
                    {option.label}
                  </label>
                ))}
              </div>
            </fieldset>
          </div>
        ))}

        <button type="submit" className="submit-btn">
          Submit Quiz
        </button>
      </form>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<Quiz />);
